enunciado:
No trecho de código a seguir, a implementação individualizada do QualityGate permite que o resultado do estágio Quality Gate 1 não interrompa o pipeline, caso o resultado da análise do SonarQube seja FAILED, e que ele prossiga normalmente para a execução do estágio SonarQube analysis 2.

```
01 pipeline {
02     agent any
03     stages {
04         stage('SonarQube analysis 1') {
05             steps {
06                 sh 'mvn clean verify org.sonarsource.scanner.maven:sonar-maven-plugin:sonar'
07             }
08         }
09         stage("Quality Gate 1") {
10             steps {
11                 waitForQualityGate abortPipeline: true
12             }
13         }
14         stage('SonarQube analysis 2') {
15             steps {
16                 sh 'gradle sonar'
17             }
18         }
19         stage("Quality Gate 2") {
20             steps {
21                 waitForQualityGate abortPipeline: true
22             }
23         }
24     }
25 }
```
